```java
package com.example.customers.domain;

import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;

public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    public static CustomerFilter none() {
        return new CustomerFilter("", Set.of());
    }

    public boolean isNone() {
        return name.isBlank() && statuses.isEmpty();
    }

    public boolean matches(Customer customer) {
        return nameMatches(customer.firstName(), customer.lastName())
                && statusMatches(customer.status());
    }

    public boolean nameMatches(String firstName, String lastName) {
        List<String> terms = terms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = fold(firstName);
        String last = fold(lastName);
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    public boolean statusMatches(CustomerStatus status) {
        return statuses.isEmpty() || statuses.contains(status);
    }

    private List<String> terms() {
        return List.of(name.trim().split("\\s+")).stream()
                .filter(t -> !t.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
    }

    private static String fold(String s) {
        String normalized = Normalizer.normalize(s, Normalizer.Form.NFD);
        StringBuilder sb = new StringBuilder(normalized.length());
        for (int i = 0; i < normalized.length(); i++) {
            char c = normalized.charAt(i);
            if (Character.getType(c) != Character.NON_SPACING_MARK) {
                sb.append(c);
            }
        }
        return sb.toString().toLowerCase(Locale.ROOT);
    }
}
```

Note: `name.trim().split("\\s+")` — for "", split returns [""] → filter out the empty element → no terms. Good. "  ada   aal  " → trim → "ada aal" → ["ada","aal"]. Good.

Case + accent folding in both directions: the query "MAKINEN" → "makinen"; the customer "Mäkinen" → "makinen" → contains → ✓. "josephine" vs "Joséphine" → "josephine" ✓.

