private static Set<CustomerStatus> parseStatuses(String parameter) {
    Set<CustomerStatus> statuses = EnumSet.noneOf(CustomerStatus.class);
    for (String part : parameter.split(",")) {
        String trimmed = part.trim();
        if (trimmed.isEmpty()) continue;
        try {
